{
  "title": "The Gilded Trap",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue party gathers at the forest's edge.",
      "visual_description": "Five figures huddle under a skeletal tree at dusk, staring across a muddy plain toward the broken spires of a ruined royal city.",
      "characters": ["map_reader", "scout", "magic_helper", "comic_relief", "bridge_crosser"]
    },
    {
      "scene_number": 2,
      "caption": "The scouts report crumbling gates and no sign of guards.",
      "visual_description": "The scout slides down a mossy bank, gesturing at the city's main gate which hangs crookedly on one hinge, ivy snaking up the iron bars.",
      "characters": ["scout", "map_reader"]
    },
    {
      "scene_number": 3,
      "caption": "The party passes under the castle gates into the outer ward.",
      "visual_description": "Weeds crack the cobblestones; a rusted portcullis looms overhead. The comic-relief trips on a loose stone, clattering loudly.",
      "characters": ["map_reader", "scout", "magic_helper", "comic_relief", "bridge_crosser"]
    },
    {
      "scene_number": 4,
      "caption": "A cursed tower beckons with a faint blue glow.",
      "visual_description": "A twisted spire pulses with cold light; runes spiral up its base. Frightened townspeople peek from boarded windows, whispering.",
      "characters": ["magic_helper", "map_reader", "frightened_townspeople"]
    },
    {
      "scene_number": 5,
      "caption": "The magic helper warns of an illusion woven into the tower's door.",
      "visual_description": "The magic helper places a hand on the door; the stone ripples like water, and a phantom feast appears inside before vanishing.",
      "characters": ["magic_helper", "bridge_crosser", "comic_relief"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon draw the party to a collapsed hall.",
      "visual_description": "Inside a roofless great hall, massive claw marks scar the floor and a single scorched royal banner hangs from a shattered beam.",
      "characters": ["scout", "map_reader", "bridge_crosser"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march through the plaza, forcing the party to hide.",
      "visual_description": "Four helmeted guards in faded livery clank across a cracked fountain square; the party presses flat behind a toppled statue.",
      "characters": ["armored_patrol", "map_reader", "scout", "magic_helper", "comic_relief", "bridge_crosser"]
    },
    {
      "scene_number": 8,
      "caption": "The comic-relief discovers a secret passage behind the royal banner.",
      "visual_description": "Tugging the scorched banner reveals a narrow stone staircase winding downward, dust motes swirling in the dim light.",
      "characters": ["comic_relief", "scout", "bridge_crosser"]
    },
    {
      "scene_number": 9,
      "caption": "The passage opens into an underground chamber with a magic door.",
      "visual_description": "A door of polished obsidian stands in the center, its surface showing shifting constellations; no handle is visible.",
      "characters": ["magic_helper", "map_reader", "comic_relief", "bridge_crosser"]
    },
    {
      "scene_number": 10,
      "caption": "The magic helper deciphers the door's riddle and opens it.",
      "visual_description": "The magic helper traces a pattern on the obsidian; the constellations align and the door dissolves into a curtain of silver light.",
      "characters": ["magic_helper", "bridge_crosser"]
    },
    {
      "scene_number": 11,
      "caption": "Beyond the door lies a treasure vault—and the captive.",
      "visual_description": "Gold coins and gem-encrusted goblets pile high; at the far end, a chained figure slumps against a pillar under a single beam of light.",
      "characters": ["map_reader", "scout", "magic_helper", "comic_relief", "bridge_crosser", "captive"]
    },
    {
      "scene_number": 12,
      "caption": "The captive is freed but alarms trigger; armored patrols block the exit.",
      "visual_description": "As the chains fall, a gong sounds; the obsidian door slams shut and armored footsteps echo from the passage.",
      "characters": ["captive", "comic_relief", "bridge_crosser", "magic_helper"]
    },
    {
      "scene_number": 13,
      "caption": "The scout finds a second route through a collapsed tower.",
      "visual_description": "The scout kicks open a rusted grate, revealing a rubble-choked tunnel sloping upward toward daylight.",
      "characters": ["scout", "map_reader", "captive"]
    },
    {
      "scene_number": 14,
      "caption": "The party emerges onto a battlement overlooking the escape bridge.",
      "visual_description": "Wind whips old royal banners as the group climbs onto a crumbling wall walk; below, a long stone bridge spans a deep gorge.",
      "characters": ["map_reader", "scout", "magic_helper", "comic_relief", "bridge_crosser", "captive"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols converge on the bridge from both sides.",
      "visual_description": "Guards stream from a gatehouse onto the bridge's far end, while more emerge behind the party; the bridge is the only way out.",
      "characters": ["armored_patrol", "map_reader", "scout", "magic_helper", "comic_relief", "bridge_crosser", "captive"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge crosser uses a rope to swing across a broken span.",
      "visual_description": "The bridge crosser hurls a grappling hook to a fallen arch, then carries the captive across hand-over-hand as stones crumble into the gorge.",
      "characters": ["bridge_crosser", "captive"]
    },
    {
      "scene_number": 17,
      "caption": "The magic helper collapses the remaining arch to block pursuers.",
      "visual_description": "The magic helper raises both hands; the stone arch groans, cracks, and crashes into the ravine, cutting off the armored patrol.",
      "characters": ["magic_helper", "comic_relief", "armored_patrol"]
    },
    {
      "scene_number": 18,
      "caption": "The party reaches the far side and vanishes into the forest.",
      "visual_description": "Dawn light filters through trees as the eight figures stumble into the treeline; behind them, the ruined city smolders under the rising sun.",
      "characters": ["map_reader", "scout", "magic_helper", "comic_relief", "bridge_crosser", "captive"]
    }
  ]
}

